<?php $items = $items ?? []; ?>
<section class="mx-auto max-w-7xl"><header class="cms-header slide-in"><div><p class="eyebrow">Admin CMS</p><h1 class="section-title mt-3">Prestasi Token</h1><p class="mt-4 max-w-2xl text-base leading-7 text-neutral-600">Buat dan kelola tautan form prestasi sekali pakai untuk pengisian dari luar admin.</p></div><button id="generate-token-btn" class="btn btn-primary" type="button">Buat Link Form Prestasi</button></header><section class="admin-card mt-6 p-4 md:p-6" id="admin-prestasi-token-list" data-ssr="true"><div class="admin-responsive-table"><table class="cms-table"><thead><tr><th>SL</th><th>Label</th><th>Status</th><th>Dibuat</th><th>Kedaluwarsa</th><th>Digunakan</th><th>Action</th></tr></thead><tbody><?php if ($items === []): ?><tr><td colspan="7" class="py-8 text-center text-neutral-500">Belum ada token.</td></tr><?php endif; ?><?php foreach ($items as $index => $item): ?><tr data-token-id="<?= (int) ($item['id'] ?? 0) ?>"><td><?= $index + 1 ?></td><td><strong><?= $e($item['label'] ?? '') ?></strong></td><td><span class="cms-pill <?= ($item['status'] ?? '') === 'active' ? 'cms-pill-green' : 'cms-pill-red' ?>"><?= $e($item['status'] ?? '') ?></span></td><td class="text-xs"><?= $e($item['created_at'] ?? '-') ?></td><td class="text-xs"><?= $e($item['expires_at'] ?? 'Tidak ada') ?></td><td class="text-xs"><?= $e($item['used_at'] ?? '-') ?></td><td><?php if (($item['status'] ?? '') === 'active'): ?><button class="cms-action delete" type="button" data-revoke data-token-id="<?= (int) ($item['id'] ?? 0) ?>">Revoke</button><?php else: ?><span class="text-neutral-400 text-xs">-</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></section>
